using UnityEngine;
using UnityEngine.InputSystem;

namespace FarmPrototype.Farming
{
    public sealed class FarmTestPlot : MonoBehaviour
    {
        private enum ToolMode
        {
            Hoe,
            Seeds,
            WateringCan,
            Harvest
        }

        [SerializeField] private string playerName = "Player";
        [SerializeField] private int gridSize = 3;
        [SerializeField] private float tileSize = 2f;
        [SerializeField] private float plotDistanceFromPlayer = 7f;
        [SerializeField] private float interactionDistance = 7f;
        [SerializeField] private float growthDuration = 10f;

        private ToolMode activeTool;
        private Transform player;
        private int harvestedCrops;
        private string feedback = "Escolha uma ferramenta e clique em um canteiro.";

        private void Start()
        {
            var playerObject = GameObject.Find(playerName);
            player = playerObject != null ? playerObject.transform : null;
            CreatePlot();
        }

        private void Update()
        {
            ReadToolSelection();

            if (Mouse.current != null && Mouse.current.leftButton.wasPressedThisFrame)
            {
                TryInteract();
            }
        }

        private void ReadToolSelection()
        {
            var keyboard = Keyboard.current;
            if (keyboard == null)
            {
                return;
            }

            if (keyboard.digit1Key.wasPressedThisFrame) activeTool = ToolMode.Hoe;
            if (keyboard.digit2Key.wasPressedThisFrame) activeTool = ToolMode.Seeds;
            if (keyboard.digit3Key.wasPressedThisFrame) activeTool = ToolMode.WateringCan;
            if (keyboard.digit4Key.wasPressedThisFrame) activeTool = ToolMode.Harvest;
        }

        private void CreatePlot()
        {
            if (player == null)
            {
                feedback = "Player não encontrado; o canteiro não foi criado.";
                return;
            }

            var forward = Camera.main != null ? Camera.main.transform.forward : player.forward;
            forward.y = 0f;
            if (forward.sqrMagnitude < 0.01f) forward = Vector3.forward;
            forward.Normalize();

            var center = player.position + (forward * plotDistanceFromPlayer);
            if (Physics.Raycast(center + (Vector3.up * 50f), Vector3.down, out var groundHit, 100f, ~0, QueryTriggerInteraction.Ignore))
            {
                center.y = groundHit.point.y;
            }

            var root = new GameObject("Farm_Test_Grid").transform;
            root.SetParent(transform, true);
            var offset = (gridSize - 1) * tileSize * 0.5f;

            for (var x = 0; x < gridSize; x++)
            {
                for (var z = 0; z < gridSize; z++)
                {
                    var tile = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    tile.name = $"Farm_Tile_{x}_{z}";
                    tile.transform.SetParent(root, true);
                    tile.transform.position = center + new Vector3((x * tileSize) - offset, 0.09f, (z * tileSize) - offset);
                    tile.transform.localScale = new Vector3(tileSize - 0.12f, 0.18f, tileSize - 0.12f);

                    var cell = tile.AddComponent<FarmPlotCell>();
                    cell.Initialize(this, growthDuration);
                }
            }

            feedback = "Canteiro de teste criado. Use 1 Enxada, 2 Sementes, 3 Regador e 4 Colher.";
        }

        private void TryInteract()
        {
            if (Camera.main == null || player == null)
            {
                return;
            }

            var ray = Camera.main.ScreenPointToRay(Mouse.current.position.ReadValue());
            foreach (var hit in Physics.RaycastAll(ray, 200f, ~0, QueryTriggerInteraction.Ignore))
            {
                var cell = hit.collider.GetComponent<FarmPlotCell>();
                if (cell == null)
                {
                    continue;
                }

                if (Vector3.Distance(player.position, cell.transform.position) > interactionDistance)
                {
                    feedback = "Chegue mais perto do canteiro para trabalhar nele.";
                    return;
                }

                feedback = cell.UseTool(activeTool, this);
                return;
            }
        }

        public void RegisterHarvest()
        {
            harvestedCrops++;
        }

        private void OnGUI()
        {
            GUI.Box(new Rect(18f, 18f, 400f, 116f), "Fazenda — teste de cultivo");
            GUI.Label(new Rect(32f, 48f, 370f, 22f), $"Ferramenta: {GetToolName(activeTool)}   |   Colheitas: {harvestedCrops}");
            GUI.Label(new Rect(32f, 72f, 370f, 22f), "1 Enxada  •  2 Sementes  •  3 Regador  •  4 Colher");
            GUI.Label(new Rect(32f, 96f, 370f, 32f), feedback);
        }

        private static string GetToolName(ToolMode tool)
        {
            return tool switch
            {
                ToolMode.Hoe => "Enxada",
                ToolMode.Seeds => "Sementes",
                ToolMode.WateringCan => "Regador",
                ToolMode.Harvest => "Colher",
                _ => "-"
            };
        }

        public sealed class FarmPlotCell : MonoBehaviour
        {
            private enum CellState
            {
                Untilled,
                Tilled,
                Seeded,
                Watered,
                Ready
            }

            private static readonly Color UntilledColor = new Color(0.33f, 0.48f, 0.18f);
            private static readonly Color TilledColor = new Color(0.28f, 0.13f, 0.05f);
            private static readonly Color SeededColor = new Color(0.40f, 0.22f, 0.08f);
            private static readonly Color WateredColor = new Color(0.12f, 0.25f, 0.18f);
            private static readonly Color ReadyColor = new Color(0.22f, 0.42f, 0.10f);

            private FarmTestPlot plot;
            private float growthDuration;
            private CellState state;
            private float wateredAt;
            private Renderer tileRenderer;
            private GameObject cropVisual;

            public void Initialize(FarmTestPlot owningPlot, float duration)
            {
                plot = owningPlot;
                growthDuration = duration;
                tileRenderer = GetComponent<Renderer>();
                RefreshVisuals();
            }

            private void Update()
            {
                if (state == CellState.Watered && Time.time >= wateredAt + growthDuration)
                {
                    state = CellState.Ready;
                    RefreshVisuals();
                }
            }

            public string UseTool(ToolMode tool, FarmTestPlot owningPlot)
            {
                switch (tool)
                {
                    case ToolMode.Hoe when state == CellState.Untilled:
                        state = CellState.Tilled;
                        RefreshVisuals();
                        return "Terra preparada. Agora plante uma semente (2).";

                    case ToolMode.Seeds when state == CellState.Tilled:
                        state = CellState.Seeded;
                        RefreshVisuals();
                        return "Semente plantada. Regue-a com a ferramenta 3.";

                    case ToolMode.WateringCan when state == CellState.Seeded:
                        state = CellState.Watered;
                        wateredAt = Time.time;
                        RefreshVisuals();
                        return $"Regado! A planta ficará pronta em {growthDuration:0} segundos.";

                    case ToolMode.Harvest when state == CellState.Ready:
                        state = CellState.Tilled;
                        owningPlot.RegisterHarvest();
                        RefreshVisuals();
                        return "Colheita obtida. O canteiro está pronto para receber outra semente.";

                    case ToolMode.Hoe:
                        return "Esse canteiro já foi preparado.";
                    case ToolMode.Seeds:
                        return "Você só pode plantar em terra preparada.";
                    case ToolMode.WateringCan:
                        return "Plante uma semente antes de regar.";
                    case ToolMode.Harvest:
                        return "A planta ainda não está pronta para a colheita.";
                    default:
                        return "Ação indisponível neste canteiro.";
                }
            }

            private void RefreshVisuals()
            {
                if (tileRenderer != null)
                {
                    tileRenderer.material.color = state switch
                    {
                        CellState.Untilled => UntilledColor,
                        CellState.Tilled => TilledColor,
                        CellState.Seeded => SeededColor,
                        CellState.Watered => WateredColor,
                        CellState.Ready => ReadyColor,
                        _ => UntilledColor
                    };
                }

                if (cropVisual != null)
                {
                    Destroy(cropVisual);
                    cropVisual = null;
                }

                if (state == CellState.Seeded || state == CellState.Watered)
                {
                    cropVisual = GameObject.CreatePrimitive(PrimitiveType.Sphere);
                    cropVisual.transform.position = transform.position + (Vector3.up * 0.3f);
                    cropVisual.transform.localScale = Vector3.one * 0.22f;
                    Destroy(cropVisual.GetComponent<Collider>());
                    cropVisual.GetComponent<Renderer>().material.color = new Color(0.85f, 0.67f, 0.22f);
                }
                else if (state == CellState.Ready)
                {
                    cropVisual = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                    cropVisual.transform.position = transform.position + (Vector3.up * 0.45f);
                    cropVisual.transform.localScale = new Vector3(0.32f, 0.45f, 0.32f);
                    Destroy(cropVisual.GetComponent<Collider>());
                    cropVisual.GetComponent<Renderer>().material.color = ReadyColor;
                }

                if (cropVisual != null)
                {
                    cropVisual.transform.SetParent(transform, true);
                }
            }
        }
    }
}
